#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
OUT_FILE="$ROOT_DIR/tests/SpanForge.Tests/Formal/SpanForgeOracle.g.cs"
CHECK_MODE=0
if [[ "${1:-}" == "--check" ]]; then
  CHECK_MODE=1
fi

TMP_DIR="$(mktemp -d)"
trap 'rm -rf "$TMP_DIR"' EXIT

dafny translate cs \
  --no-verify \
  --include-runtime:false \
  -o "$TMP_DIR/oracle" \
  "$ROOT_DIR/formal/CodecBijections.dfy" \
  "$ROOT_DIR/formal/DnsTermination.dfy" \
  "$ROOT_DIR/formal/StreamingAndProtocols.dfy"

{
  cat <<'EOF'
// <auto-generated>
// Generated by formal/generate-oracle.sh via `dafny translate cs` from the
// formally verified Dafny specifications in `formal/`. Do not edit by hand.
// </auto-generated>
#nullable disable
#pragma warning disable

using System;
using System.Numerics;
using System.Collections;

EOF
  awk '/^namespace Dafny \{/{flag=1} flag{print}' "$TMP_DIR/oracle.cs"
} > "$TMP_DIR/SpanForgeOracle.g.cs"

if [[ "$CHECK_MODE" -eq 1 ]]; then
  if ! diff -u "$OUT_FILE" "$TMP_DIR/SpanForgeOracle.g.cs"; then
    echo "ERROR: tests/SpanForge.Tests/Formal/SpanForgeOracle.g.cs is out of sync with formal/*.dfy." >&2
    echo "Run ./formal/generate-oracle.sh to regenerate." >&2
    exit 1
  fi
  echo "OK: SpanForgeOracle.g.cs matches verified formal/*.dfy."
else
  mkdir -p "$(dirname "$OUT_FILE")"
  cp "$TMP_DIR/SpanForgeOracle.g.cs" "$OUT_FILE"
  echo "Generated $OUT_FILE ($(wc -l < "$OUT_FILE") lines)."
fi
